 async function pinHash(bookingId:string,code:string){if(pinSecret.length<32)fail(503,'Trip-code service is not configured');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pinSecret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return Array.from(new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(bookingId+':'+code)))).map(b=>b.toString(16).padStart(2,'0')).join('')}
 const q=(sql:string,...args:any[])=>db.prepare(sql).bind(...args),one=async(sql:string,...args:any[])=>q(sql,...args).first(),all=async(sql:string,...args:any[])=>(await q(sql,...args).all()).results;
 const log=(a:Actor,target:string,action:string,details:unknown={})=>q('INSERT INTO audit(id,actor_id,target,action,details,created_at) VALUES(?,?,?,?,?,?)',id(),a.id,target,action,encode(details),now());
 const notification=(user:string,message:string)=>q('INSERT INTO notifications(id,user_id,message,created_at) VALUES(?,?,?,?)',id(),user,message,now());
